//! @file
//! @brief Container Transparency support
#pragma once

#include "../Hash.h"

#include "../cpp/StringView.h"

#include <type_traits>

namespace carb::container
{
//! \cond DEV
namespace detail
{
template <typename T, typename = void>
struct IsTransparent : std::false_type
{
};

template <typename T>
struct IsTransparent<T, std::void_t<typename T::is_transparent>> : std::true_type
{
};
} // namespace detail
//! \endcond

/**
 * String hasher that supports transparency.
 * \details A string comparator for unordered maps, sets and any other containers that work based on a Hasher that use a
 * string as a key (omni::string, std::string, carb::RString) and are transparently comparable with `const char*` or
 * anything that can be used to construct a carb::cpp::string_view.
 */
struct TransparentStringHasher : public std::equal_to<void>
{
    //! Declaration of transparency support.
    using is_transparent = void;

    //! Hash for carb::cpp::string_view
    //! @param sv The string view
    //! @returns Hash value for the string view.
    size_t operator()(cpp::string_view sv) const
    {
        return carb::hashBuffer(sv.data(), sv.length());
    }
    //! Hash for a raw C string. Treats `nullptr` as an empty string.
    //! @param p The raw C string.
    //! @returns Hash value for the string view.
    size_t operator()(const char* p) const
    {
        if (!p)
            p = "";
        return carb::hashString(p);
    }

    //! Inherit std::equal_to<void> support.
    using std::equal_to<void>::operator();
};
static_assert(detail::IsTransparent<TransparentStringHasher>::value);
static_assert(detail::IsTransparent<std::equal_to<void>>::value); // check assumptions

/**
 * String (lexicographical) less-than-comparator for ordered maps and sets.
 * @details A string comparator for ordered maps and sets that use a string as a key (omni::string or std::string) and
 * are transparently comparable with `const char*` or anything that can be used to construct a carb::cpp::string_view.
 * @note This is merely an alias for `std::less<void>`, a transparent comparator.
 */
using TransparentStringLessCompare = std::less<void>; // the default C++14 std::less<void> supports transparency
static_assert(detail::IsTransparent<std::less<void>>::value); // check assumptions

} // namespace carb::container
